/**
 * A planet's plants and leaves, swaying in its wind — CODE-SPLIT.
 *
 * A REGISTERED CHUNK MANIFEST MODULE (MANIFEST_MODULES and ALLOWLIST in
 * tooling/check-shader-imports.mjs): the import site of `MaterialPluginBase`
 * for the sway, loaded only by dynamic `import()` from the planet view, so a
 * world whose plants stand still never fetches it.
 *
 * A material plugin on every lit material named `leaves` or `plants` (the
 * blocks' chunks). In its vertices it moves the world position along the
 * ground by the sway sway.ts lays out: a plant's points weighed by the first
 * of their second texture coordinates (0 at the foot, 1 at the top), which
 * the chunk carries; a plant whose chunk carries none is left standing still.
 * Leaves sway whole. The displacement is a function of the world position, so
 * faces sharing a corner move together. Nothing changes in the fragments.
 *
 * The sway's numbers are written out from the reference's own tables, so the
 * two cannot drift apart. As waterReflectChunk.ts does, the code is written
 * in WGSL for WebGPU and GLSL for WebGL2, chosen by the material's shader
 * language. The two are kept in step.
 */
import { ShaderLanguage } from '@babylonjs/core/Materials/shaderLanguage';
import { MaterialPluginBase } from '@babylonjs/core/Materials/materialPluginBase';
import { ShadowDepthWrapper } from '@babylonjs/core/Materials/shadowDepthWrapper';
import type { UniformBuffer } from '@babylonjs/core/Materials/uniformBuffer';
import type { AbstractMesh } from '@babylonjs/core/Meshes/abstractMesh';
import type { Scene } from '@babylonjs/core/scene';
import { materialArrivals } from './materialArrivals';
import { isAway, takePlugin } from './awayMaterials';
import { SWAY_FLUTTER_FLOOR, SWAY_GUSTS, SWAY_LEAVES, SWAY_PLANT, SWAY_SIDE_SPREAD, SWAY_SPREAD, f, type SwayHandle, type SwayKind, type SwayState } from './sway';

/** Every input the sway takes, in both languages. */
export const SWAY_UNIFORMS = ['swayOrigin', 'swayWind', 'swaySide', 'swayStrength', 'swayPhase', 'swayGust'] as const;

const UNIFORMS_GLSL = `#ifdef SWAY
uniform vec3 swayOrigin;
uniform vec3 swayWind;
uniform vec3 swaySide;
uniform float swayStrength;
uniform vec4 swayPhase;
uniform vec2 swayGust;
#endif
`;

const UNIFORMS_WGSL = `#ifdef SWAY
uniform swayOrigin: vec3f;
uniform swayWind: vec3f;
uniform swaySide: vec3f;
uniform swayStrength: f32;
uniform swayPhase: vec4f;
uniform swayGust: vec2f;
#endif
`;

/** The gusts' sum and a kind's motion, as each language writes them; `u` is how the language reaches a uniform. */
function body(u: (name: string) => string, decl: 'float' | 'let'): { gust: string; plant: string; leaves: string } {
  const gust = SWAY_GUSTS.map(
    ([down, across, share], i) => `${f(share)} * sin(6.2831853 / ${f(down)} * a + 6.2831853 / ${f(across)} * b - ${u('swayGust')}.${'xy'[i]})`,
  ).join(' + ');
  const kind = (k: SwayKind, phases: string) =>
    `  ${decl} down = (${f(k.lean)} + ${f(k.gust)} * g + ${f(k.flutter)} * swing * sin(${u('swayPhase')}.${phases[0]} + spread)) * scale;
  ${decl} across = ${f(k.side)} * swing * sin(${u('swayPhase')}.${phases[1]} + ${f(SWAY_SIDE_SPREAD)} * spread) * scale;`;
  return { gust, plant: kind(SWAY_PLANT, 'xy'), leaves: kind(SWAY_LEAVES, 'zw') };
}

function definitionsGlsl(): string {
  const b = body((n) => n, 'float');
  return `#ifdef SWAY
#if defined(SWAYWEIGHT) && !defined(UV2)
attribute vec2 uv2;
#endif
// How far the wind moves the world point p, weighed 0 (held) to 1: along the ground, with the wind and across it.
vec3 swayOffset(vec3 p, float weight) {
  float scale = weight * swayStrength;
  if (scale == 0.0) return vec3(0.0);
  vec3 r = p - swayOrigin;
  float a = dot(r, swayWind);
  float b = dot(r, swaySide);
  float g = 0.5 + ${b.gust};
  g = g * g;
  float spread = ${f(SWAY_SPREAD[0])} * a + ${f(SWAY_SPREAD[1])} * b;
  float swing = ${f(SWAY_FLUTTER_FLOOR)} + g;
#ifdef SWAYPLANT
${b.plant}
#else
${b.leaves}
#endif
  return swayWind * down + swaySide * across;
}
#endif
`;
}

function definitionsWgsl(): string {
  const b = body((n) => `uniforms.${n}`, 'let');
  return `#ifdef SWAY
#if defined(SWAYWEIGHT) && !defined(UV2)
attribute uv2: vec2f;
#endif
fn swayOffset(p: vec3f, weight: f32) -> vec3f {
  let scale = weight * uniforms.swayStrength;
  if (scale == 0.0) { return vec3f(0.0); }
  let r = p - uniforms.swayOrigin;
  let a = dot(r, uniforms.swayWind);
  let b = dot(r, uniforms.swaySide);
  var g: f32 = 0.5 + ${b.gust};
  g = g * g;
  let spread = ${f(SWAY_SPREAD[0])} * a + ${f(SWAY_SPREAD[1])} * b;
  let swing = ${f(SWAY_FLUTTER_FLOOR)} + g;
#ifdef SWAYPLANT
${b.plant}
#else
${b.leaves}
#endif
  return uniforms.swayWind * down + uniforms.swaySide * across;
}
#endif
`;
}

export interface SwayCode {
  uniforms: string;
  /** Declared once, before the material's vertex main. */
  definitions: string;
  /** In the vertices, on the world position before it is drawn. */
  vertex: string;
}

/** The sway's code for a material: WGSL on WebGPU, GLSL elsewhere. */
export function selectSwayCode(engineKind?: string): SwayCode {
  if (engineKind === 'webgpu') {
    return {
      uniforms: UNIFORMS_WGSL,
      definitions: definitionsWgsl(),
      vertex: `#ifdef SWAY
#ifdef SWAYPLANT
#ifdef SWAYWEIGHT
worldPos = vec4f(worldPos.xyz + swayOffset(worldPos.xyz, vertexInputs.uv2.x), worldPos.w);
#endif
#else
worldPos = vec4f(worldPos.xyz + swayOffset(worldPos.xyz, 1.0), worldPos.w);
#endif
#endif
`,
    };
  }
  return {
    uniforms: UNIFORMS_GLSL,
    definitions: definitionsGlsl(),
    vertex: `#ifdef SWAY
#ifdef SWAYPLANT
#ifdef SWAYWEIGHT
worldPos.xyz += swayOffset(worldPos.xyz, uv2.x);
#endif
#else
worldPos.xyz += swayOffset(worldPos.xyz, 1.0);
#endif
#endif
`,
  };
}

const PLUGIN_NAME = 'Sway';

class SwayPlugin extends MaterialPluginBase {
  private _isEnabled = true;

  constructor(
    material: ConstructorParameters<typeof MaterialPluginBase>[0],
    private state: { now: SwayState | null },
  ) {
    super(material, PLUGIN_NAME, 320, { SWAY: false, SWAYPLANT: false, SWAYWEIGHT: false }, true, true);
  }

  /** Draws from another planet's state from now on (awayMaterials.ts). */
  rebind(state: { now: SwayState | null }): void {
    this.state = state;
  }

  /** A plant, weighed point by point; otherwise leaves, swaying whole. Read from the base's material, as the manager asks for code inside the base's constructor. */
  private get plant(): boolean {
    return this._material.name === 'plants';
  }

  get isEnabled(): boolean {
    return this._isEnabled;
  }

  set isEnabled(value: boolean) {
    if (this._isEnabled === value) return;
    this._isEnabled = value;
    this.markAllDefinesAsDirty();
    this._enable(value);
  }

  override getClassName(): string {
    return 'SwayPlugin';
  }

  override isCompatible(shaderLanguage: ShaderLanguage): boolean {
    return shaderLanguage === ShaderLanguage.GLSL || shaderLanguage === ShaderLanguage.WGSL;
  }

  /** Whether this mesh's points carry their weights. */
  private weighed(mesh: AbstractMesh | undefined): boolean {
    return this.plant && mesh !== undefined && mesh.isVerticesDataPresent('uv2');
  }

  override prepareDefines(defines: Parameters<MaterialPluginBase['prepareDefines']>[0], _scene: Scene, mesh: AbstractMesh): void {
    const d = defines as unknown as Record<string, boolean>;
    d['SWAY'] = this._isEnabled;
    d['SWAYPLANT'] = this._isEnabled && this.plant;
    d['SWAYWEIGHT'] = this._isEnabled && this.weighed(mesh);
  }

  override getAttributes(attributes: string[], _scene: Scene, mesh: AbstractMesh): void {
    // The material asks for them itself where it draws a texture by them.
    if (this._isEnabled && this.weighed(mesh) && !attributes.includes('uv2')) attributes.push('uv2');
  }

  override getUniforms(shaderLanguage: ShaderLanguage = ShaderLanguage.GLSL) {
    return {
      ubo: [
        { name: 'swayOrigin', size: 3, type: 'vec3' },
        { name: 'swayWind', size: 3, type: 'vec3' },
        { name: 'swaySide', size: 3, type: 'vec3' },
        { name: 'swayStrength', size: 1, type: 'float' },
        { name: 'swayPhase', size: 4, type: 'vec4' },
        { name: 'swayGust', size: 2, type: 'vec2' },
      ],
      vertex: shaderLanguage === ShaderLanguage.WGSL ? UNIFORMS_WGSL : UNIFORMS_GLSL,
    };
  }

  override bindForSubMesh(ubo: UniformBuffer): void {
    if (!this._isEnabled) return;
    const s = this.state.now;
    if (!s) {
      ubo.updateFloat('swayStrength', 0);
      return;
    }
    ubo.updateFloat3('swayOrigin', s.origin[0], s.origin[1], s.origin[2]);
    ubo.updateFloat3('swayWind', s.wind[0], s.wind[1], s.wind[2]);
    ubo.updateFloat3('swaySide', s.side[0], s.side[1], s.side[2]);
    ubo.updateFloat('swayStrength', s.strength);
    ubo.updateFloat4('swayPhase', s.phase[0], s.phase[1], s.phase[2], s.phase[3]);
    ubo.updateFloat2('swayGust', s.gust[0], s.gust[1]);
  }

  override getCustomCode(shaderType: string, shaderLanguage: ShaderLanguage = ShaderLanguage.GLSL): { [pointName: string]: string } | null {
    if (shaderType !== 'vertex') return null;
    const code = selectSwayCode(shaderLanguage === ShaderLanguage.WGSL ? 'webgpu' : 'webgl2');
    return { CUSTOM_VERTEX_DEFINITIONS: code.definitions, CUSTOM_VERTEX_UPDATE_WORLDPOS: code.vertex };
  }
}

/** What sways: lit materials named `leaves` or `plants`. */
const sways = (m: Scene['materials'][number]): boolean => {
  if (m.name !== 'leaves' && m.name !== 'plants') return false;
  const kind = m.getClassName();
  return kind === 'StandardMaterial' || kind === 'PBRMaterial';
};

/**
 * Sway every lit material named `leaves` or `plants` in the scene, and each
 * one that arrives (from the next `update`). `dispose` stills them all and
 * adds it to no more.
 */
/**
 * Where the shadow code finds the world position and normal in a lit
 * material's vertex shader: its own names on WebGL; on WebGPU the WGSL vertex
 * keeps the normal in its outputs, which the shadow's normal bias must be told.
 */
function shadowNamesFor(engineKind: string | undefined): { remappedVariables: string[] } | undefined {
  return engineKind === 'webgpu' ? { remappedVariables: ['worldPos', 'worldPos', 'vNormalW', 'vertexOutputs.vNormalW'] } : undefined;
}

type ReadyArgs = Parameters<ShadowDepthWrapper['isReadyForSubMesh']>;

/**
 * A swaying material's shadow, made from the material's own draw state, and
 * not ready while the material has lost that state: a plugin added to a
 * material that has drawn throws it away, and a shadow made then would bind
 * nothing (on WebGPU the frame fails, and the view stops drawing). It is ready
 * again once the material has drawn.
 *
 * Babylon names each sub-mesh's shadow shader by a random token, so no two
 * share one: every chunk that arrives makes its shadow shader again, which
 * takes hundreds of milliseconds of the frame, and on WebGPU builds its own
 * shadow pipeline too. The shadow shader is made from the
 * material's own effect alone, and the engine shares effects between materials
 * with the same defines, so every sub-mesh drawn with the same effect is given
 * the same token here, and their shadows share one shader and one pipeline.
 */
const shadowTokens = new WeakMap<object, string>();
let shadowTokenCount = 0;

class SwayShadow extends ShadowDepthWrapper {
  constructor(...args: ConstructorParameters<typeof ShadowDepthWrapper>) {
    super(...args);
    const self = this as unknown as {
      _subMeshToEffect: Map<unknown, [object, number]>;
      _subMeshToDepthWrapper: { set(subMesh: unknown, generator: unknown, params: { token: string }): void };
    };
    const byPair = self._subMeshToDepthWrapper;
    const set = byPair.set.bind(byPair);
    byPair.set = (subMesh, generator, params) => {
      const effect = self._subMeshToEffect.get(subMesh)?.[0];
      if (effect) {
        let token = shadowTokens.get(effect);
        if (token === undefined) shadowTokens.set(effect, (token = `swayShadow${shadowTokenCount++}`));
        params.token = token;
      }
      set(subMesh, generator, params);
    };
  }

  override isReadyForSubMesh(...args: ReadyArgs): boolean {
    const subMesh = args[0] as ReadyArgs[0] & { _getDrawWrapper(pass?: number): { defines: unknown } | undefined };
    const from = (this as unknown as { _subMeshToEffect: Map<unknown, [unknown, number]> })._subMeshToEffect.get(subMesh);
    if (from && !subMesh._getDrawWrapper(from[1])?.defines) return false;
    return super.isReadyForSubMesh(...args);
  }
}

export function createSwayOn(scene: Scene, opts: { engineKind?: string }): SwayHandle {
  const shadowNames = shadowNamesFor(opts.engineKind);
  const shared: { now: SwayState | null } = { now: null };
  const plugins: SwayPlugin[] = [];
  // The shadow maps draw a material's own vertex shader, the sway in it, only through a depth wrapper: given to each
  // swaying material that has none of its own, and taken back with the sway.
  const wrapped: { material: Scene['materials'][number]; wrapper: ShadowDepthWrapper }[] = [];
  // Every material in the scene, and each one as it arrives: a chunk's leaves and plants sway from the next frame.
  const arrivals = materialArrivals(scene);
  const attachAll = () =>
    arrivals.take((m) => {
      if (sways(m) && isAway(m)) return false;
      const p = sways(m) ? takePlugin(m, PLUGIN_NAME, shared, () => new SwayPlugin(m, shared)) : undefined;
      if (p) {
        plugins.push(p);
        if (!m.shadowDepthWrapper) {
          const wrapper = new SwayShadow(m, scene, shadowNames);
          m.shadowDepthWrapper = wrapper;
          wrapped.push({ material: m, wrapper });
        }
      }
    });
  attachAll();
  let stopped = false;
  return {
    update(s) {
      if (stopped) return;
      attachAll();
      shared.now = s;
    },
    dispose() {
      stopped = true;
      arrivals.dispose();
      for (const p of plugins) p.isEnabled = false;
      plugins.length = 0;
      for (const { material, wrapper } of wrapped) {
        if (material.shadowDepthWrapper === wrapper) material.shadowDepthWrapper = null;
        wrapper.dispose();
      }
      wrapped.length = 0;
    },
  };
}
